"""
UTC-PD 30μm Simulation & S11 Fitting
=====================================
V_bias = -7V

Circuit topology (ADS):
  I_ph ↑ ‖ C_PD ── Rs ── Node B ──── L_CPW ──── R_L (50Ω)
                          │       │
                        C_CPW    R_p
                          │       │
                         GND     GND

  Y_B    = jω·C_CPW + 1/R_p + 1/(jω·L_CPW + R_L)
  H_ckt  = [R_L/(R_L + jω·L_CPW)] / [jω·C_PD + Y_B·(1 + jω·Rs·C_PD)]
  S11    = (Z_in − 50)/(Z_in + 50)
  Z_in   = jω·L_CPW + 1/(jω·C_CPW + 1/R_p + 1/(Rs + 1/(jω·C_PD)))
  P_RL   = |I_ph · H_ph · H_ckt|² / (2·R_L)

CPW parameters fixed (Open-device ADS Momentum):
  C_CPW = 28.93 fF,  L_CPW = 218.9 pH  (no skin-effect R)

Fitting strategy:
  - Open         : Rs=7.54Ω, Cj=132.2fF, L_CPW=218.9pH all fixed (ADS values)
  - 200Ω         : Rs=7.54Ω fixed, Cj=132.2fF fixed, L_CPW only free
  - 38Ω, 59Ω    : Rs=7.54Ω fixed, Cj+L_CPW joint fit (S11 + freq response)
"""

import numpy as np
import matplotlib
import matplotlib.pyplot as plt
from scipy.optimize import differential_evolution, minimize
import pandas as pd

# ═══════════════════════════════════════════════════════════════════════
# 1. CPW PARAMETERS  (fixed, Open-device ADS Momentum)
# ═══════════════════════════════════════════════════════════════════════
C_CPW = 28.93e-15   # F
L_CPW = 218.9e-12   # H
R_L   = 50.0        # Ω

# ═══════════════════════════════════════════════════════════════════════
# 2. DEVICE / BIAS PARAMETERS
# ═══════════════════════════════════════════════════════════════════════
I_ph = 1.0 * (30/40)**2 * 1e-3   # A  (1mA × area scaling, 30μm)

# ═══════════════════════════════════════════════════════════════════════
# 3. TRANSIT TIMES & H_ph(ω)
# ═══════════════════════════════════════════════════════════════════════
v_os_InP    = 2.3e7 * 1e-2   # m/s
v_os_InGaAs = 2.1e7 * 1e-2   # m/s
W_A_undep = 480e-9; W_A_dep = 160e-9; W_cliff = 50e-9; W_C = 740e-9
W_tot = W_A_undep + W_A_dep + W_cliff + W_C
tau_A  = 7.862e-12
tau_Ad = W_A_dep / v_os_InGaAs
tau_cl = W_cliff  / v_os_InP
tau_C  = W_C      / v_os_InP

def H_ph(w):
    sinc = lambda x: np.sinc(x / np.pi)
    HA   = 1 / (1 + 1j*w*tau_A)
    HAd  = sinc(w*tau_Ad/2) * np.exp(-1j*(w*tau_A + w*tau_Ad/2))
    Hcl  = sinc(w*tau_cl/2) * np.exp(-1j*(w*tau_A + w*tau_Ad + w*tau_cl/2))
    Hco  = sinc(w*tau_C/2)  * np.exp(-1j*(w*tau_A + w*tau_Ad + w*tau_cl + w*tau_C/2))
    return (W_A_undep*HA + W_A_dep*HAd + W_cliff*Hcl + W_C*Hco) / W_tot

# ═══════════════════════════════════════════════════════════════════════
# 4. CIRCUIT FUNCTIONS
# ═══════════════════════════════════════════════════════════════════════
def H_ckt(w, Rs, Cpd, Rp, Lcpw=L_CPW):
    Y_B = (1j*w*C_CPW
           + (0 if np.isinf(Rp) else 1/Rp)
           + 1/(1j*w*Lcpw + R_L))
    return R_L / (R_L + 1j*w*Lcpw) / (1j*w*Cpd + Y_B*(1 + 1j*w*Rs*Cpd))

def sim_S11(w, Rs, Cpd, Rp, Lcpw=L_CPW):
    Z_dev  = Rs + 1/(1j*w*Cpd)
    Y_node = (1j*w*C_CPW
              + (0 if np.isinf(Rp) else 1/Rp)
              + 1/Z_dev)
    Z_in   = 1j*w*Lcpw + 1/Y_node
    return (Z_in - 50) / (Z_in + 50)

def P_RL_dBm(I_ph_A, w, Rs, Cpd, Rp, Lcpw=L_CPW):
    Ht  = H_ph(w) * H_ckt(w, Rs, Cpd, Rp, Lcpw)
    P_W = I_ph_A**2 * np.abs(Ht)**2 / (2*R_L)
    return 10*np.log10(np.maximum(P_W, 1e-30) / 1e-3)

def get_bw(f, w, Rs, Cpd, Rp, Lcpw=L_CPW):
    Ht = H_ph(w) * H_ckt(w, Rs, Cpd, Rp, Lcpw)
    Hd = 20*np.log10(np.abs(Ht) / np.abs(Ht[0]))
    idx = np.where(Hd <= -3)[0]
    return f[idx[0]]/1e9 if len(idx) else np.nan

