# ═══════════════════════════════════════════════════════════════════════
# 6. DATA ACCESS
# ═══════════════════════════════════════════════════════════════════════
def get_s1p(arr, f_max):
    fr = arr[:,0]
    S11 = 10**(arr[:,1]/20) * np.exp(1j*np.deg2rad(arr[:,2]))
    mask = fr <= f_max
    return fr[mask], S11[mask]

def get_freq_response(arr):
    f_ghz = arr[:,0]
    cal   = arr[:,1] + np.interp(f_ghz, ref_f_GHz, ref_loss_dB)
    return f_ghz * 1e9, cal - cal[0]

# ═══════════════════════════════════════════════════════════════════════
# 7. FITTING
# ═══════════════════════════════════════════════════════════════════════
# Fixed for all devices (from Open ADS values)
Rs_fixed  = 7.54      # Ω
Cj_fixed  = 132.2e-15 # F
# Bounds
L_BOUNDS  = (87e-12, 350e-12)      # L_CPW: ±60% around ADS nominal
Cj_BOUNDS = (50e-15, 300e-15)      # Cj for joint fit
Rs_BOUNDS = (1.0, 25.0)            # Rs (Ω) for 3-param joint fit

def fit_lcpw(s1p_arr, freq_arr, Rp):
    """Fit L_CPW only. Rs and Cj are fixed."""
    fm, _      = get_freq_response(freq_arr)
    fs11, S11m = get_s1p(s1p_arr, fm.max())
    w = 2*np.pi*fs11
    def cost(p):
        return np.mean(np.abs(sim_S11(w, Rs_fixed, Cj_fixed, Rp, p[0]) - S11m)**2)
    best_c, best_L = np.inf, L_CPW
    for L_try in np.linspace(L_BOUNDS[0]*1e12, L_BOUNDS[1]*1e12, 1000):
        c = cost([L_try*1e-12])
        if c < best_c: best_c, best_L = c, L_try*1e-12
    pol = minimize(cost, [best_L], method='L-BFGS-B', bounds=[L_BOUNDS],
                   options={'ftol':1e-16, 'gtol':1e-12, 'maxiter':10000})
    return pol.x[0], Cj_fixed  # L_CPW, Cj

def fit_joint_cj_lcpw(s1p_arr, freq_arr, Rp, w_s11=1.0, w_freq=0.005):
    """Joint fit: Cj + L_CPW free, Rs fixed.
    Cost = w_s11 * mean|S11_sim - S11_meas|^2
         + w_freq * mean(H_sim_dB - H_meas_dB)^2
    """
    fm, pm     = get_freq_response(freq_arr)
    fs11, S11m = get_s1p(s1p_arr, fm.max())
    w_s = 2*np.pi*fs11
    w_f = 2*np.pi*fm
    def cost(p):
        Cj_try, Lcpw_try = p
        S11s = sim_S11(w_s, Rs_fixed, Cj_try, Rp, Lcpw_try)
        c_s11 = np.mean(np.abs(S11s - S11m)**2)
        Ht = H_ph(w_f) * H_ckt(w_f, Rs_fixed, Cj_try, Rp, Lcpw_try)
        Hd = 20*np.log10(np.abs(Ht) / np.abs(Ht[0]))
        c_freq = np.mean((Hd - pm)**2)
        return w_s11 * c_s11 + w_freq * c_freq
    bounds = [Cj_BOUNDS, L_BOUNDS]
    res_de = differential_evolution(cost, bounds, seed=42,
                                    maxiter=2000, tol=1e-14,
                                    polish=False, popsize=30)
    res = minimize(cost, res_de.x, method='L-BFGS-B', bounds=bounds,
                   options={'ftol':1e-16, 'gtol':1e-12, 'maxiter':10000})
    return res.x[1], res.x[0]  # L_CPW, Cj

def fit_joint_rs_cj_lcpw(s1p_arr, freq_arr, Rp, w_s11=1.0, w_freq=0.02):
    """Joint fit: Rs + Cj + L_CPW all free.
    3 free params give better frequency-response matching.
    Cost = w_s11 * mean|S11_sim - S11_meas|^2
         + w_freq * mean(H_sim_dB - H_meas_dB)^2
    w_freq=0.02 (4x higher than 2-param) to emphasise freq response.
    """
    fm, pm     = get_freq_response(freq_arr)
    fs11, S11m = get_s1p(s1p_arr, fm.max())
    w_s = 2*np.pi*fs11
    w_f = 2*np.pi*fm
    def cost(p):
        Rs_try, Cj_try, Lcpw_try = p
        S11s  = sim_S11(w_s, Rs_try, Cj_try, Rp, Lcpw_try)
        c_s11 = np.mean(np.abs(S11s - S11m)**2)
        Ht    = H_ph(w_f) * H_ckt(w_f, Rs_try, Cj_try, Rp, Lcpw_try)
        Hd    = 20*np.log10(np.abs(Ht) / np.abs(Ht[0]))
        c_freq = np.mean((Hd - pm)**2)
        return w_s11 * c_s11 + w_freq * c_freq
    bounds = [Rs_BOUNDS, Cj_BOUNDS, L_BOUNDS]
    res_de = differential_evolution(cost, bounds, seed=42,
                                    maxiter=3000, tol=1e-14,
                                    polish=False, popsize=30)
    res = minimize(cost, res_de.x, method='L-BFGS-B', bounds=bounds,
                   options={'ftol':1e-16, 'gtol':1e-12, 'maxiter':10000})
    return res.x[2], res.x[1], res.x[0]  # L_CPW, Cj, Rs

