def draw_smith(ax):
    ax.set_xlim(-1.1,1.1); ax.set_ylim(-1.1,1.1)
    ax.set_aspect('equal'); ax.axis('off')
    ax.add_patch(plt.Circle((0,0),1,fill=False,color='gray',lw=0.8))
    ax.axhline(0,color='gray',lw=0.5)
    for r in [0,0.2,0.5,1,2,5]:
        cx, rad = r/(r+1), 1/(r+1)
        ax.add_patch(plt.Circle((cx,0),rad,fill=False,color='gray',lw=0.4,ls=':'))
        if r > 0: ax.text(cx+rad+0.02, 0.02, f'{r}', fontsize=6, color='gray')
    theta = np.linspace(0, np.pi, 300)
    for x in [0.2,0.5,1,2,5]:
        for sgn in [1,-1]:
            cx, cy, rad = 1, sgn/x, 1/abs(x)
            ax_x = cx + rad*np.cos(theta); ay = cy + rad*np.sin(theta)*sgn
            m = (ax_x**2 + ay**2 <= 1.001)
            ax.plot(ax_x[m], ay[m], 'gray', lw=0.4, ls=':')

