# 12. DC & RF POWER PLOTS
# ═══════════════════════════════════════════════════════════════════════

def P_RL_plus_Rp_dBm(I_ph_A, w, Rs, Cpd, Rp, Lcpw=L_CPW):
    """Total RF power delivered to R_L and Rp combined."""
    Ht  = H_ph(w) * H_ckt(w, Rs, Cpd, Rp, Lcpw)
    P_RL_W = I_ph_A**2 * np.abs(Ht)**2 / (2*R_L)
    if np.isinf(Rp):
        return 10*np.log10(np.maximum(P_RL_W, 1e-30) / 1e-3)
    factor = np.abs(1.0 + 1j*w*Lcpw/R_L)**2
    P_Rp_W = I_ph_A**2 * np.abs(Ht)**2 * factor / (2*Rp)
    return 10*np.log10(np.maximum(P_RL_W + P_Rp_W, 1e-30) / 1e-3)

# ── helper: parallel resistance ──────────────────────────────────────
def _Rpar(Rp, RL):
    return RL if np.isinf(Rp) else Rp*RL / (Rp + RL)

# ── measured saturation data loader ──────────────────────────────────
def _load_sat_data(xlsx_path, is_wo=False):
    """Extract Iph(mA) and Cal RF(dBm) for Bias=-3 V from saturation xlsx.

    With-resistor layout (col indices, 0-based):
      0:Total current | 1:Photocurrent(mA) | 2:Output power | 3:Loss | 4:Cal RF | 5:Real photocurrent
      → iph_col=5 (Real photocurrent = Total − dark current), calrf_col=4

    WO layout:
      0:Photocurrent(mA) | 1:Output power | 2:Loss | 3:Cal RF
      → iph_col=0, calrf_col=3

    Rows with an empty leading cell are shifted +1; both positions are tried.
    Rows where the Real photocurrent cell is empty are skipped.
    """
    import zipfile, xml.etree.ElementTree as ET

    with zipfile.ZipFile(xlsx_path) as z:
        ns0 = {'ns': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
        try:
            root_ss = ET.fromstring(z.read('xl/sharedStrings.xml'))
            strings = [t.text or ''
                       for si in root_ss.findall('ns:si', ns0)
                       for t  in si.findall('.//ns:t', ns0)]
        except Exception:
            strings = []

        root_ws = ET.fromstring(z.read('xl/worksheets/sheet1.xml'))
        all_rows = []
        for row in root_ws.findall('.//ns:row', ns0):
            vals = []
            for c in row.findall('ns:c', ns0):
                v = c.find('ns:v', ns0)
                val = v.text if v is not None else ''
                if c.get('t', '') == 's' and val:
                    val = strings[int(val)]
                vals.append(val)
            all_rows.append(vals)

    # Column layout depends on file type
    if is_wo:
        iph_col, calrf_col = 0, 3   # Photocurrent(mA), Cal RF
    else:
        iph_col, calrf_col = 5, 4   # Real photocurrent, Cal RF

    in_section   = False
    header_found = False
    iph_list, pout_list = [], []

    def _try_float(row, idx):
        try:
            v = str(row[idx]).strip()
            return float(v) if v else None
        except Exception:
            return None

    for row in all_rows:
        s0 = str(row[0]).strip() if row else ''

        # Detect section boundaries via "Bias" row
        if s0 == 'Bias':
            try:
                in_section   = (float(str(row[1]).strip()) == -3.0)
                header_found = False
            except Exception:
                in_section = False
            continue

        # A new "Diameter" row ends the current section
        if s0 == 'Diameter' and in_section and header_found:
            break

        if not in_section:
            continue

        # Detect column-header row
        if not header_found:
            if 'Photocurrent' in ' '.join(str(v) for v in row):
                header_found = True
            continue

        row = list(row) + [''] * 12   # pad so index access never raises

        # Try primary positions
        iph  = _try_float(row, iph_col)
        pout = _try_float(row, calrf_col)
        if iph is not None and iph > 0 and pout is not None:
            iph_list.append(iph)
            pout_list.append(pout)
            continue

        # Try shifted (+1) for rows with an empty leading cell
        iph  = _try_float(row, iph_col  + 1)
        pout = _try_float(row, calrf_col + 1)
        if iph is not None and iph > 0 and pout is not None:
            iph_list.append(iph)
            pout_list.append(pout)

    iph_arr  = np.array(iph_list,  dtype=float)
    pout_arr = np.array(pout_list, dtype=float)
    order    = np.argsort(iph_arr)
    return iph_arr[order], pout_arr[order]

